import { dedupePreservingOrder } from "../../util/collections.js";

import type { EntityId, EpisodeId, StreamEntryId } from "../../util/ids.js";

import { isoInstantEpochMsSchema } from "../../util/iso-instant.js";

import { valueAppearsIn } from "../../util/text-presence.js";

import type { OfflineContext } from "../types.js";

function entryContent(entry: StreamEntry): string {
  return [
    renderFrameAnomalyAnnotations(entry.frame_anomalies),
    typeof entry.content === "string"
      ? entry.content
      : (JSON.stringify(entry.content) ?? String(entry.content)),
  ]
    .filter(Boolean)
    .join("\n");
}

function formatIdList(ids: readonly string[]): string {
  return ids.length === 0 ? "none" : ids.join(", ");
}

function sourceEpisodeLabels(
  sourceEpisodes: readonly OverseerSourceEpisode[],
): ReadonlyMap<EpisodeId, MemoryDisclosureLabel> {
  return new Map(
    sourceEpisodes.map((episode) => [episode.id, memoryDisclosureLabelFromEpisodeAccess(episode)]),
  );
}

function sourceEntryDisclosureLabel(
  source: OverseerResolvedSourceEntry,
  labelsByEpisodeId: ReadonlyMap<EpisodeId, MemoryDisclosureLabel>,
): MemoryDisclosureLabel {
  if (source.source_episode_ids.length === 0) {
    return unknownMemoryDisclosureLabel();
  }

  return combineMemoryDisclosureLabels(
    source.source_episode_ids.map(
      (episodeId) => labelsByEpisodeId.get(episodeId) ?? unknownMemoryDisclosureLabel(),
    ),
  );
}

export function renderSourceBundleForPrompt(bundle: OverseerSourceBundle): string {
  const lines = [
    "Target source grounding:",
    `target_type: ${bundle.target_type}`,
    `target_id: ${bundle.target_id}`,
    `source_episode_ids: ${formatIdList(bundle.source_episode_ids)}`,
    `source_stream_ids: ${formatIdList(bundle.source_stream_ids)}`,
  ];

  if (bundle.source_episodes.length === 0) {
    lines.push("Source episode audience tags: none");
  } else {
    lines.push("Source episode audience tags:");

    for (const episode of bundle.source_episodes) {
      lines.push(
        `EPISODE episode_id=${episode.id} audience_entity_id=${episode.audience_entity_id ?? "none"} origin_audience_entity_ids=${formatIdList(episode.origin_audience_entity_ids)} shared=${String(episode.shared)}`,
      );
    }
  }

  if (bundle.audience_entities.length === 0) {
    lines.push("Audience entity metadata: none");
  } else {
    lines.push("Audience entity metadata:");

    for (const audience of bundle.audience_entities) {
      lines.push(
        `AUDIENCE entity_id=${audience.entity_id} display_name=${JSON.stringify(audience.display_name)} source_episode_ids=${formatIdList(audience.source_episode_ids)}`,
      );
    }
  }

  if (bundle.missing_episode_ids.length > 0) {
    lines.push(
      `PROVENANCE-INSUFFICIENT missing source_episode_ids: ${formatIdList(bundle.missing_episode_ids)}`,
    );
  }

  if (bundle.missing_stream_ids.length > 0) {
    lines.push(
      `PROVENANCE-INSUFFICIENT missing source_stream_ids: ${formatIdList(bundle.missing_stream_ids)}`,
    );
  }

  if (bundle.entries.length === 0) {
    lines.push("Resolved source entries: none");
    return lines.join("\n");
  }

  lines.push("Resolved source entries:");
  const labelsByEpisodeId = sourceEpisodeLabels(bundle.source_episodes);

  for (const [index, source] of bundle.entries.entries()) {
    const disclosureFields = memoryDisclosurePayloadFields(
      sourceEntryDisclosureLabel(source, labelsByEpisodeId),
    );

    lines.push(
      [
        `SOURCE[${index}] source_episode_ids=${formatIdList(source.source_episode_ids)} session_id=${source.entry.session_id} timestamp=${source.entry.timestamp} timestamp_iso=${new Date(source.entry.timestamp).toISOString()} stream_id=${source.entry.id} kind=${source.entry.kind} disclosure=${JSON.stringify(disclosureFields.disclosure)} disclosure_label=${JSON.stringify(disclosureFields.disclosure_label)}`,
        entryContent(source.entry),
      ].join("\n"),
    );
  }

  return lines.join("\n");
}
export { renderSourceBundleForPrompt };
